#[derive(Debug, Clone, PartialEq, Eq)] pub enum ActionState { Proposed, Approved, Started, EffectApplied, Confirmed, Failed }
#[derive(Debug, Clone, PartialEq, Eq)] pub struct Action { pub id: String, pub capability: String, pub scope: String, pub risk: u8, pub state: ActionState }
impl Action { pub fn approve(&mut self, allowed: bool) -> Result<(), &'static str> { if self.state != ActionState::Proposed { return Err("invalid transition") } if !allowed { self.state = ActionState::Failed; return Err("capability denied") } self.state = ActionState::Approved; Ok(()) } pub fn start(&mut self) -> Result<(), &'static str> { if self.state != ActionState::Approved { return Err("invalid transition") } self.state = ActionState::Started; Ok(()) } pub fn effect_applied(&mut self) -> Result<(), &'static str> { if self.state != ActionState::Started { return Err("invalid transition") } self.state = ActionState::EffectApplied; Ok(()) } pub fn confirm(&mut self, oracle_passed: bool) -> Result<(), &'static str> { if self.state != ActionState::EffectApplied { return Err("invalid transition") } self.state = if oracle_passed { ActionState::Confirmed } else { ActionState::Failed }; Ok(()) } }
